#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Mahayuddh: social sign-in (GitHub, GitLab, Google, LinkedIn, X, Apple).
#
# Creates nothing itself: you create each OAuth app in its provider's console,
# this script tells you exactly what to fill in and captures the client ID and
# secret. At the end it switches the providers on in Supabase through the
# Management API (PATCH /v1/projects/<ref>/config/auth), sending ONLY the
# provider fields plus Site URL and redirect URLs: no other auth setting moves.
#
# Values are kept in ~/.config/mahayuddh/oauth.env (mode 600, outside the
# repo), so a re-run only asks for what changed. Apple's secret expires every
# 6 months: re-run, skip the others, paste the new Apple secret.
#
# Run: bash scripts/setup-social-login.sh

umask 077
ENV_FILE="${ENV_FILE:-$HOME/.config/mahayuddh/oauth.env}"
mkdir -p "$(dirname "$ENV_FILE")"

PROJECT_REF="purvcivaijjjtgknqvqn"
SITE_URL="https://mahayuddh.vercel.app"
CALLBACK_URL="https://${PROJECT_REF}.supabase.co/auth/v1/callback"
API="https://api.supabase.com/v1/projects/${PROJECT_REF}/config/auth"
ENABLED=()   # providers to switch on in the final stage

for bin in curl python3; do
  command -v "$bin" >/dev/null 2>&1 || { printf 'This wizard needs %s.\n' "$bin"; exit 1; }
done

# api METHOD [json-file] calls the Management API without putting the token
# or the secrets on a command line: both go through files only you can read.
api() {
  local method="$1" body="${2:-}" cfg out
  cfg=$(mktemp); out=$(mktemp)
  printf 'header = "Authorization: Bearer %s"\nheader = "Content-Type: application/json"\n' \
    "$SUPABASE_ACCESS_TOKEN" > "$cfg"
  local code
  if [[ -n "$body" ]]; then
    code=$(curl -sS -K "$cfg" -X "$method" --data-binary "@$body" -o "$out" -w '%{http_code}' "$API" || true)
  else
    code=$(curl -sS -K "$cfg" -X "$method" -o "$out" -w '%{http_code}' "$API" || true)
  fi
  rm -f "$cfg"
  API_STATUS="$code"; API_BODY_FILE="$out"
}

show_callback() {
  say ""
  say "${BOLD}Callback / redirect URL${RESET} (paste exactly):"
  say "  ${GREEN}${CALLBACK_URL}${RESET}"
  say ""
}

# want "Label": y/N gate for setting up one provider this run.
want() {
  if confirm "Set up $1 now? (No skips it; a re-run can add it later)"; then return 0; fi
  note "Skipped $1."; pause; return 1
}

TOTAL_STAGES=9

banner "Mahayuddh · social sign-in"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase access token"
say "The last stage switches providers on through Supabase's Management API."
say "That needs a personal access token from your Supabase account."
open_url "https://supabase.com/dashboard/account/tokens"
step "Click 'Generate new token', name it e.g. 'mahayuddh social login', copy it."
note "Revoke it on the same page when you're done if you won't re-run this."
ask_secret SUPABASE_ACCESS_TOKEN "Paste the token:"
api GET
if [[ "$API_STATUS" != "200" ]]; then
  warn "Supabase answered HTTP $API_STATUS. Check the token and that it can see project $PROJECT_REF."
  rm -f "$API_BODY_FILE"; exit 1
fi
write_env SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
cp "$API_BODY_FILE" "$ENV_FILE.current-auth.json"; rm -f "$API_BODY_FILE"
python3 -I - "$ENV_FILE.current-auth.json" <<'PY'
import json, sys
c = json.load(open(sys.argv[1]))
on = [p for p in ("github", "gitlab", "google", "linkedin_oidc", "x", "apple") if c.get(f"external_{p}_enabled")]
print(f"  Site URL now:       {c.get('site_url')}")
print(f"  Redirect URLs now:  {c.get('uri_allow_list') or '(none)'}")
print(f"  Confirm email:      {'OFF (people are signed in straight away)' if c.get('mailer_autoconfirm') else 'ON (people must click an email link)'}")
print(f"  Providers on now:   {', '.join(on) or '(none)'}")
PY
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub"
if want "GitHub"; then
  open_url "https://github.com/settings/applications/new"
  step "Application name: Mahayuddh"
  step "Homepage URL: $SITE_URL"
  step "Authorization callback URL: the URL below. Leave 'Enable Device Flow' unchecked."
  show_callback
  step "Click 'Register application', copy the Client ID."
  ask GITHUB_CLIENT_ID "GitHub Client ID:"
  step "Click 'Generate a new client secret', copy it (shown once)."
  ask_secret GITHUB_SECRET "GitHub client secret:"
  write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"; write_env GITHUB_SECRET "$GITHUB_SECRET"
  ENABLED+=(github)
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitLab"
if want "GitLab"; then
  open_url "https://gitlab.com/-/user_settings/applications"
  step "Add a new application. Name: Mahayuddh"
  step "Redirect URI: the URL below."
  show_callback
  step "Tick 'Confidential'. Scope: tick ${BOLD}read_user${RESET} only. Save the application."
  step "Copy the Application ID and the Secret."
  ask GITLAB_CLIENT_ID "GitLab Application ID:"
  ask_secret GITLAB_SECRET "GitLab Secret:"
  write_env GITLAB_CLIENT_ID "$GITLAB_CLIENT_ID"; write_env GITLAB_SECRET "$GITLAB_SECRET"
  ENABLED+=(gitlab)
  pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google"
if want "Google"; then
  say "Part 1 · consent screen (Google Auth Platform). Create or pick a project first."
  open_url "https://console.cloud.google.com/auth/overview"
  step "Branding: app name Mahayuddh, your support email, home page $SITE_URL,"
  step "  privacy $SITE_URL/privacy, terms $SITE_URL/terms (if the fields are shown)."
  step "Audience: External."
  step "Data Access: keep only openid, userinfo.email, userinfo.profile (no others)."
  note "With only those basic scopes, any Google account can sign in while the app"
  note "is in Testing; 'Publish app' on the Audience page moves it to production."
  pause "Consent screen done? Press Enter for the client."
  say "Part 2 · OAuth client."
  open_url "https://console.cloud.google.com/auth/clients"
  step "Create client → Application type: Web application, name Mahayuddh."
  step "Authorized JavaScript origins: $SITE_URL"
  step "Authorized redirect URIs: the URL below."
  show_callback
  step "Create, then copy the Client ID and Client secret."
  ask GOOGLE_CLIENT_ID "Google Client ID:"
  ask_secret GOOGLE_SECRET "Google Client secret:"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"; write_env GOOGLE_SECRET "$GOOGLE_SECRET"
  ENABLED+=(google)
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "LinkedIn"
warn "LinkedIn requires a LinkedIn Page to attach the app to."
if want "LinkedIn"; then
  open_url "https://www.linkedin.com/developers/apps/new"
  step "Create app: name Mahayuddh, pick your LinkedIn Page, upload a logo, save."
  step "Products tab: 'Sign In with LinkedIn using OpenID Connect' → Request access."
  step "Auth tab → Authorized redirect URLs for your app → add the URL below."
  show_callback
  step "Auth tab: copy the Client ID and the Client Secret."
  step "Check 'OAuth 2.0 scopes' lists openid, profile and email."
  ask LINKEDIN_CLIENT_ID "LinkedIn Client ID:"
  ask_secret LINKEDIN_SECRET "LinkedIn Client Secret:"
  write_env LINKEDIN_CLIENT_ID "$LINKEDIN_CLIENT_ID"; write_env LINKEDIN_SECRET "$LINKEDIN_SECRET"
  ENABLED+=(linkedin_oidc)
  pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "X (Twitter)"
if want "X"; then
  open_url "https://developer.x.com/en/portal/dashboard"
  step "Create a Project and an App (name Mahayuddh). Ignore the API Key / Secret it shows."
  step "App settings → User authentication settings → Set up."
  step "App permissions: Read. Turn ON 'Request email from users'."
  step "Type of App: Web App. Callback URL: the URL below."
  show_callback
  step "Website URL $SITE_URL · Terms $SITE_URL/terms · Privacy $SITE_URL/privacy → Save."
  step "Keys and tokens → OAuth 2.0 Client ID and Client Secret (bottom of the page)."
  step "Copy the Client ID; Regenerate the Client Secret and copy it."
  ask X_CLIENT_ID "X OAuth 2.0 Client ID:"
  ask_secret X_SECRET "X OAuth 2.0 Client Secret:"
  write_env X_CLIENT_ID "$X_CLIENT_ID"; write_env X_SECRET "$X_SECRET"
  ENABLED+=(x)
  pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Apple"
warn "Apple needs a paid Apple Developer Program membership (99 USD/year), and"
warn "its secret expires every 6 months: re-run this wizard to rotate it."
if want "Apple"; then
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Note your Team ID (top right of the developer site)."
  step "Identifiers → + → App IDs: e.g. com.mahayuddh.app, enable 'Sign in with Apple'."
  step "Identifiers → + → Services IDs: e.g. com.mahayuddh.web. Enable Sign in with Apple,"
  step "  Configure: primary App ID above, Domain ${PROJECT_REF}.supabase.co,"
  step "  Return URL: the URL below."
  show_callback
  step "Keys → + : enable Sign in with Apple, download the .p8 (one download only)."
  step "Then generate the client secret with the tool on Supabase's Apple page"
  step "  (Chrome or Firefox, not Safari): Team ID, Services ID, Key ID, .p8."
  pause "Press Enter to open that page."
  open_url "https://supabase.com/docs/guides/auth/social-login/auth-apple"
  ask APPLE_SERVICES_ID "Services ID (e.g. com.mahayuddh.web):"
  ask_secret APPLE_SECRET "Generated Apple client secret (a long JWT):"
  write_env APPLE_SERVICES_ID "$APPLE_SERVICES_ID"; write_env APPLE_SECRET "$APPLE_SECRET"
  write_env APPLE_SECRET_SET_ON "$(date +%F)"
  ENABLED+=(apple)
  pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Switch them on in Supabase"
if (( ${#ENABLED[@]} == 0 )); then
  warn "No providers chosen this run; nothing to change."
  pause
else
  say "This will turn ON: ${BOLD}${ENABLED[*]}${RESET}"
  say "and set Site URL to $SITE_URL, adding $SITE_URL/** to the redirect URLs"
  say "(existing redirect URLs are kept). Nothing else in Supabase changes."
  if confirm "Apply now?"; then
    body=$(mktemp)
    ENABLED_LIST="${ENABLED[*]}" SITE_URL="$SITE_URL" \
    GITHUB_CLIENT_ID="${GITHUB_CLIENT_ID:-}" GITHUB_SECRET="${GITHUB_SECRET:-}" \
    GITLAB_CLIENT_ID="${GITLAB_CLIENT_ID:-}" GITLAB_SECRET="${GITLAB_SECRET:-}" \
    GOOGLE_CLIENT_ID="${GOOGLE_CLIENT_ID:-}" GOOGLE_SECRET="${GOOGLE_SECRET:-}" \
    LINKEDIN_CLIENT_ID="${LINKEDIN_CLIENT_ID:-}" LINKEDIN_SECRET="${LINKEDIN_SECRET:-}" \
    X_CLIENT_ID="${X_CLIENT_ID:-}" X_SECRET="${X_SECRET:-}" \
    APPLE_SERVICES_ID="${APPLE_SERVICES_ID:-}" APPLE_SECRET="${APPLE_SECRET:-}" \
    python3 -I - "$ENV_FILE.current-auth.json" "$body" <<'PY'
import json, os, sys
current = json.load(open(sys.argv[1]))
site = os.environ["SITE_URL"]
allow = [u.strip() for u in (current.get("uri_allow_list") or "").split(",") if u.strip()]
for u in (f"{site}/**",):
    if u not in allow:
        allow.append(u)
patch = {"site_url": site, "uri_allow_list": ",".join(allow)}
ids = {"github": "GITHUB_CLIENT_ID", "gitlab": "GITLAB_CLIENT_ID", "google": "GOOGLE_CLIENT_ID",
       "linkedin_oidc": "LINKEDIN_CLIENT_ID", "x": "X_CLIENT_ID", "apple": "APPLE_SERVICES_ID"}
secrets = {"github": "GITHUB_SECRET", "gitlab": "GITLAB_SECRET", "google": "GOOGLE_SECRET",
           "linkedin_oidc": "LINKEDIN_SECRET", "x": "X_SECRET", "apple": "APPLE_SECRET"}
missing = []
for p in os.environ["ENABLED_LIST"].split():
    cid, sec = os.environ.get(ids[p], "").strip(), os.environ.get(secrets[p], "").strip()
    if not cid or not sec:
        missing.append(p); continue
    patch[f"external_{p}_enabled"] = True
    patch[f"external_{p}_client_id"] = cid
    patch[f"external_{p}_secret"] = sec
if missing:
    print("  missing ID or secret for: " + ", ".join(missing) + " (left unchanged)")
json.dump(patch, open(sys.argv[2], "w"))
PY
    api PATCH "$body"; rm -f "$body"
    if [[ "$API_STATUS" == "200" ]]; then
      printf '  %s✓ Supabase updated%s\n' "$GREEN" "$RESET"
    else
      warn "Supabase answered HTTP $API_STATUS:"
      python3 -I -c "import json,sys; b=open(sys.argv[1]).read(); print('  ', b[:400])" "$API_BODY_FILE"
      SKIPPED+=("Supabase PATCH failed (HTTP $API_STATUS); re-run stage 8")
    fi
    rm -f "$API_BODY_FILE"
  else
    SKIPPED+=("providers captured but not switched on; re-run and apply")
  fi
  pause
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
