print(f"  Site URL:                 {c.get('site_url')}")
print(f"  Redirect URLs:            {c.get('uri_allow_list')}")
PY
else
  warn "Couldn't read the settings back (HTTP $API_STATUS)."
fi
rm -f "$API_BODY_FILE"
